//! The Unicode tables `{:?}` needs to escape characters as rustc's
//! `char::escape_debug` does: rustc's `is_printable` and its
//! `Grapheme_Extend` lookup, Unicode 17.0.0, with their
//! tables copied from rustc's `core/src/unicode/printable.rs` (generated
//! by its `printable.py`) and `unicode_data.rs` (generated by its
//! `unicode-table-generator`). Regenerate them together when rustc's
//! Unicode version changes.

fn check(x: u16, singletonuppers: &[(u8, u8)], singletonlowers: &[u8], normal: &[u8]) -> bool {
    let xupper = (x >> 8) as u8;
    let mut lowerstart = 0;
    let mut i = 0;
    while i < singletonuppers.len() {
        let (upper, lowercount) = singletonuppers[i];
        let lowerend = lowerstart + lowercount as usize;
        if xupper == upper {
            let mut j = lowerstart;
            while j < lowerend {
                if singletonlowers[j] == x as u8 {
                    return false;
                }
                j += 1;
            }
        } else if xupper < upper {
            break;
        }
        lowerstart = lowerend;
        i += 1;
    }

    let mut x = x as i32;
    let mut current = true;
    let mut k = 0;
    while k < normal.len() {
        let v = normal[k];
        k += 1;
        let len = if v & 0x80 != 0 {
            let next = normal[k];
            k += 1;
            ((v & 0x7f) as i32) << 8 | next as i32
        } else {
            v as i32
        };
        x -= len;
        if x < 0 {
            break;
        }
        current = !current;
    }
    current
}

/// Whether `{:?}` shows the character as it is (rustc's
/// `core::unicode::printable::is_printable`).
pub(crate) fn is_printable(x: char) -> bool {
    // The tables below are from rustc's nightly of 2026-03-21; the
    // stable rustc flux is compared with (1.99) has newer ones, which make
    // the Hangul fillers unprintable. Drop this when regenerating them.
    if matches!(x, '\u{115F}' | '\u{1160}' | '\u{3164}' | '\u{FFA0}') {
        return false;
    }
    let x = x as u32;
    let lower = x as u16;

    if x < 32 {
        // ASCII fast path
        false
    } else if x < 127 {
        // ASCII fast path
        true
    } else if x < 0x10000 {
        check(lower, &SINGLETONS0U, &SINGLETONS0L, &NORMAL0)
    } else if x < 0x20000 {
        check(lower, &SINGLETONS1U, &SINGLETONS1L, &NORMAL1)
    } else {
        if 0x2a6e0 <= x && x < 0x2a700 {
            return false;
        }
        if 0x2b81e <= x && x < 0x2b820 {
            return false;
        }
        if 0x2ceae <= x && x < 0x2ceb0 {
            return false;
        }
        if 0x2ebe1 <= x && x < 0x2ebf0 {
            return false;
        }
        if 0x2ee5e <= x && x < 0x2f800 {
            return false;
        }
        if 0x2fa1e <= x && x < 0x30000 {
            return false;
        }
        if 0x3134b <= x && x < 0x31350 {
            return false;
        }
        if 0x3347a <= x && x < 0xe0100 {
            return false;
        }
        if 0xe01f0 <= x && x < 0x110000 {
            return false;
        }
        true
    }
}

