/// Whether the character extends a grapheme (rustc's
/// `char::is_grapheme_extended`, through `unicode_data::grapheme_extend`).
pub(crate) fn is_grapheme_extended(c: char) -> bool {
    let needle = c as u32;
    // Not grapheme-extending in rustc 1.99's tables, newer than these
    // (see `is_printable`).
    if needle < 0x300 || needle == 0xFF9E || needle == 0xFF9F {
        return false;
    }
    // rustc's `skip_search`: each run is `start_index << 21 | prefix_sum`.
    let runs = &GRAPHEME_EXTEND_RUNS;
    let mut lo = 0;
    let mut hi = runs.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        let key = runs[mid] << 11;
        if key == needle << 11 {
            lo = mid + 1;
            break;
        } else if key < needle << 11 {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    let last_idx = lo;
    let mut offset_idx = (runs[last_idx] >> 21) as usize;
    let length = if last_idx + 1 < runs.len() {
        (runs[last_idx + 1] >> 21) as usize - offset_idx
    } else {
        GRAPHEME_EXTEND_OFFSETS.len() - offset_idx
    };
    let prev = if last_idx > 0 {
        runs[last_idx - 1] & ((1 << 21) - 1)
    } else {
        0
    };
    let total = needle - prev;
    let mut prefix_sum = 0;
    let mut n = 0;
    while n + 1 < length {
        prefix_sum += GRAPHEME_EXTEND_OFFSETS[offset_idx] as u32;
        if prefix_sum > total {
            break;
        }
        offset_idx += 1;
        n += 1;
    }
    offset_idx % 2 == 1
}

